"""Suspension-tower invariant table for the RP^2 pseudomanifold family.

Builds the k-fold suspension of the minimal six-vertex projective plane and
reports, for each k, the dimension, vertex count, facet count, face vector,
Euler characteristic, and whether the weak-pseudomanifold property holds.
"""
from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, List, Set

Facet = FrozenSet[int]

RP2: Set[Facet] = {frozenset(t) for t in [
    (0,1,2),(0,2,3),(0,3,4),(0,4,5),(0,1,5),
    (1,2,4),(1,3,4),(1,3,5),(2,3,5),(2,4,5)]}

def suspend(F: Set[Facet], a: int, b: int) -> Set[Facet]:
    return {s | {a} for s in F} | {s | {b} for s in F}

def tower(F: Set[Facet], k: int) -> Set[Facet]:
    cur, nxt = set(F), max(max(s) for s in F) + 1
    for _ in range(k):
        cur = suspend(cur, nxt, nxt + 1); nxt += 2
    return cur

def face_vector(F: Set[Facet]) -> List[int]:
    top = max(len(s) for s in F)
    layers: List[Set[Facet]] = [set() for _ in range(top)]
    for s in F:
        for k in range(1, len(s) + 1):
            for f in combinations(sorted(s), k):
                layers[k - 1].add(frozenset(f))
    return [len(x) for x in layers]

def euler(F: Set[Facet]) -> int:
    return sum((-1)**i * fi for i, fi in enumerate(face_vector(F)))

def is_weak_pmfd(F: Set[Facet], d: int) -> bool:
    if any(len(s) != d + 1 for s in F): return False
    ridges: Set[Facet] = set()
    for s in F:
        for r in combinations(sorted(s), d): ridges.add(frozenset(r))
    return all(sum(1 for s in F if r <= s) == 2 for r in ridges)

if __name__ == "__main__":
    for k in range(6):
        F = tower(RP2, k); d = 2 + k
        nv = len({v for s in F for v in s})
        print(f"k={k} d={d} verts={nv} facets={len(F)} "
              f"fvec={tuple(face_vector(F))} chi={euler(F)} "
              f"weak_pmfd={is_weak_pmfd(F, d)}")

