function IsWeakPseudomanifold(F, d):
    for sigma in F:
        if |sigma| != d+1: return False        # purity
    R <- {}                                      # ridge -> incident facet count
    for sigma in F:
        for rho in d-subsets(sigma):
            R[rho] <- R[rho] + 1
    for rho in R:
        if R[rho] != 2: return False             # non-branching
    return True

