function Handshake(F, d):
    f_d   <- |F|
    R     <- union over sigma in F of d-subsets(sigma)
    f_dm1 <- |R|
    return ( (d+1)*f_d , 2*f_dm1 , (d+1)*f_d == 2*f_dm1 )

function Suspend(F, a, b):
    return { sigma + {a} : sigma in F } union { sigma + {b} : sigma in F }

function IteratedSuspension(F, k):
    next <- 1 + max vertex label in F
    for i in 1..k:
        F <- Suspend(F, next, next+1)
        next <- next + 2
    return F

